Here is the commit message:
wifi: mt76: Fix possible oob access in
 mt76_connac2_mac_write_txwi_80211()

Check frame length before accessing the mgmt fields in
mt76_connac2_mac_write_txwi_80211 in order to avoid a possible oob
access.

Fixes: 577dbc6c656d ("mt76: mt7915: enable offloading of sequence number assignment")
Signed-off-by: Lorenzo Bianconi <lorenzo@kernel.org>
Link: https://patch.msgid.link/20260226-mt76-addba-req-oob-access-v1-3-b0f6d1ad4850@kernel.org
[fix check to also cover mgmt->u.action.u.addba_req.capab,
correct Fixes tag]
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The function mt76_connac2_mac_write_txwi_80211 did not validate the length of the skb before accessing management frame fields such as mgmt->u.action.category, mgmt->u.action.u.addba_req.action_code, and mgmt->u.action.u.addba_req.capab, leading to a possible out-of-bounds read when processing a short or malformed action frame.

Here is the patch:

 static void
 mt76_connac2_mac_write_txwi_80211(struct mt76_dev *dev, __le32 *txwi,
 				  struct sk_buff *skb,
 				  struct ieee80211_key_conf *key)
 {
 	struct ieee80211_hdr *hdr = (struct ieee80211_hdr *)skb->data;
 	struct ieee80211_mgmt *mgmt = (struct ieee80211_mgmt *)skb->data;
 	struct ieee80211_tx_info *info = IEEE80211_SKB_CB(skb);
 	bool multicast = is_multicast_ether_addr(hdr->addr1);
 	u8 tid = skb->priority & IEEE80211_QOS_CTL_TID_MASK;
 	__le16 fc = hdr->frame_control;
 	__le16 sc = hdr->seq_ctrl;
 	u8 fc_type, fc_stype;
 	u32 val;

 	if (ieee80211_is_action(fc) &&
+	    skb->len >= IEEE80211_MIN_ACTION_SIZE + 1 + 1 + 2 &&
 	    mgmt->u.action.category == WLAN_CATEGORY_BACK &&
 	    mgmt->u.action.u.addba_req.action_code == WLAN_ACTION_ADDBA_REQ) {
 		u16 capab = le16_to_cpu(mgmt->u.action.u.addba_req.capab);

 		txwi[5] |= cpu_to_le32(MT_TXD5_ADD_BA);
 		tid = (capab >> 2) & IEEE80211_QOS_CTL_TID_MASK;
 	} else if (ieee80211_is_back_req(hdr->frame_control)) {
 		struct ieee80211_bar *bar = (struct ieee80211_bar *)hdr;
 		u16 control = le16_to_cpu(bar->control);

 		tid = FIELD_GET(IEEE80211_BAR_CTRL_TID_INFO_MASK, control);
 	}

 	val = FIELD_PREP(MT_TXD1_HDR_FORMAT, MT_HDR_FORMAT_802_11) |
 	      FIELD_PREP(MT_TXD1_HDR_INFO,
 			 ieee80211_get_hdrlen_from_skb(skb) / 2) |
 	      FIELD_PREP(MT_TXD1_TID, tid);

 	txwi[1] |= cpu_to_le32(val);

 	fc_type = (le16_to_cpu(fc) & IEEE80211_FCTL_FTYPE) >> 2;
 	fc_stype = (le16_to_cpu(fc) & IEEE80211_FCTL_STYPE) >> 4;

 	val = FIELD_PREP(MT_TXD2_FRAME_TYPE, fc_type) |
 	      FIELD_PREP(MT_TXD2_SUB_TYPE, fc_stype) |
 	      FIELD_PREP(MT_TXD2_MULTICAST, multicast);

 	if (key && multicast && ieee80211_is_robust_mgmt_frame(skb) &&
 	    key->cipher == WLAN_CIPHER_SUITE_AES_CMAC) {
 		val |= MT_TXD2_BIP;
 		txwi[3] &= ~cpu_to_le32(MT_TXD3_PROTECT_FRAME);
 	}

 	if (!ieee80211_is_data(fc) || multicast ||
 	    info->flags & IEEE80211_TX_CTL_USE_MINRATE)
 		val |= MT_TXD2_FIX_RATE;

 	if (ieee80211_has_morefrags(fc) && ieee80211_is_first_frag(sc))
 		val |= FIELD_PREP(MT_TXD2_FRAG, MT_TX_FRAG_FIRST);
 	else if (ieee80211_has_morefrags(fc) && !ieee80211_is_first_frag(sc))
 		val |= FIELD_PREP(MT_TXD2_FRAG, MT_TX_FRAG_MID);
 	else if (!ieee80211_has_morefrags(fc) && !ieee80211_is_first_frag(sc))
 		val |= FIELD_PREP(MT_TXD2_FRAG, MT_TX_FRAG_LAST);

 	txwi[2] |= cpu_to_le32(val);

 	if (ieee80211_is_beacon(fc)) {
 		txwi[3] &= ~cpu_to_le32(MT_TXD3_SW_POWER_MGMT);
 		txwi[3] |= cpu_to_le32(MT_TXD3_REM_TX_COUNT);
 	}

 	if (info->flags & IEEE80211_TX_CTL_INJECTED) {
 		u16 seqno = le16_to_cpu(sc);

 		if (ieee80211_is_back_req(hdr->frame_control)) {
 			struct ieee80211_bar *bar;

 			bar = (struct ieee80211_bar *)skb->data;
 			seqno = le16_to_cpu(bar->start_seq_num);
 		}

 		val = MT_TXD3_SN_VALID |
 		      FIELD_PREP(MT_TXD3_SEQ, IEEE80211_SEQ_TO_SN(seqno));
 		txwi[3] |= cpu_to_le32(val);
 		txwi[7] &= ~cpu_to_le32(MT_TXD7_HW_AMSDU);
 	}

 	if (mt76_is_mmio(dev)) {
 		val = FIELD_PREP(MT_TXD7_TYPE, fc_type) |
 		      FIELD_PREP(MT_TXD7_SUB_TYPE, fc_stype);
 		txwi[7] |= cpu_to_le32(val);
 	} else {
 		val = FIELD_PREP(MT_TXD8_L_TYPE, fc_type) |
 		      FIELD_PREP(MT_TXD8_L_SUB_TYPE, fc_stype);
 		txwi[8] |= cpu_to_le32(val);
 	}
 }



